// Ratecard static generator. Node 20+, no dependencies. Usage: node scripts/build.mjs  (SITE_URL env for prod)
import fs from 'node:fs';import path from 'node:path';import {scheduleGuard,forecast} from '../src/pricing.js';
const root=path.resolve(path.dirname(new URL(import.meta.url).pathname),'..');const R=p=>path.join(root,p);const D=R('dist');
const SITE=(process.env.SITE_URL||'https://ratecardai.pages.dev').replace(/\/$/,'');
// ---- Go-live constants (replace '#pending' when Kit / checkout exist)
const FORM_ACTION='https://app.kit.com/forms/10107382/subscriptions';            // Kit form action URL, e.g. https://app.kit.com/forms/XXXX/subscriptions
const CHECKOUT_PRO_MONTHLY='https://o11y-watch.kit.com/products/ratecard-pro';   // $9/mo
const CHECKOUT_PRO_ANNUAL='https://o11y-watch.kit.com/products/ratecard-pro';    // $90/yr
const CHECKOUT_SPONSOR='https://o11y-watch.kit.com/products/ratecard-sponsor-slot-founding';       // founding sponsor slot
const CONTACT='mailto:basileion.ops@gmail.com';                // mailto: once an inbox exists
const LEGAL_UPDATED='2026-11-07'; // privacy/terms/about (RT-20261031-64 / RT-20261107-10)
const NAME='Ratecard';
// SEO head slot: tags pasted into seo/head-extra.html (HTML comments stripped) are injected into every page's <head>.
const HEADSLOT='<!-- seo-meta-slot: edit seo/head-extra.html -->'+(fs.existsSync(R('seo/head-extra.html'))?fs.readFileSync(R('seo/head-extra.html'),'utf8'):'').replace(/<!--[\s\S]*?-->/g,'').trim();
// IndexNow (Bing/Yandex): key lives in indexnow.key; build hosts it at /<key>.txt. Submit with `node scripts/indexnow.mjs`.
const INDEXNOW_KEY=fs.existsSync(R('indexnow.key'))?fs.readFileSync(R('indexnow.key'),'utf8').trim():'';
const rd=f=>JSON.parse(fs.readFileSync(R('data/'+f),'utf8'));
const models=rd('models.json'),providers=rd('providers.json'),changes=rd('changes.json').sort((a,b)=>b.observed.localeCompare(a.observed)||a.date.localeCompare(b.date));
const SCHED=rd('scheduled.json');SCHED.billing_rules=SCHED.billing_rules||[];
// Scheduled list-price changes ride along on each model row (api/models.json) so the calculator can price the next 12 months (RT-20261031-98).
models.forEach(m=>{const r=SCHED.increases.filter(x=>x.model_id===m.id);if(r.length)m.scheduled_changes=r.map(x=>({dimension:x.dimension,old:x.old,new:x.new,effective:x.effective,source:x.source,checked:x.checked}))});
// Guard (RT-20261031-98): every calculator model with a future scheduled change must get a dated note + a 12-month total that applies it. Negative tests must fail.
{const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/New_York'});const errs=scheduleGuard(models,today);
if(errs.length){console.error('BUILD GUARD (scheduled changes): '+errs.join(' | '));process.exit(1)}
const fake={id:'neg-test',kind:'text',input:1,output:2,cached:0.1,scheduled_changes:[{dimension:'input',old:1,new:2,effective:'2999-01-01'}]};
const neg1=scheduleGuard([fake],today,(m,u,o)=>({...forecast(m,u,o),notes:[]})),neg2=scheduleGuard([{...fake,scheduled_changes:[{dimension:'mystery tier',old:1,new:2,effective:'2999-01-01'}]}],today),neg3=scheduleGuard([{...fake,input:1.5}],today);
if(!neg1.length||!neg2.length||!neg3.length){console.error('BUILD GUARD (scheduled changes): negative test did not fail',neg1,neg2,neg3);process.exit(1)}
console.log('guard ok: scheduled-change notes ('+models.filter(m=>m.scheduled_changes&&m.kind==='text').length+' text models), negative tests failed as expected ('+[neg1,neg2,neg3].map(x=>x.length).join('/')+')')}
// Guard (RT-20261031-14): rows whose vendor publishes a long-context price tier must carry long_context, or finder/calculator underprice long prompts.
{const LC_REQUIRED=['openai-gpt-6-astra','openai-gpt-6-1-sol','openai-gpt-6-luna','openai-gpt-5-6-sol','anthropic-claude-haiku-5-5','google-gemini-3-1-pro-preview','xai-grok-4-7','openrouter-grok-4-7-spacexai','openai-gpt-6-1-terra','openai-gpt-6-sol','openai-gpt-5-6-terra','openai-gpt-5-6-luna','openai-gpt-5-5','openai-gpt-5-5-pro','openai-gpt-5-4','openai-gpt-5-4-pro'];
const bad=LC_REQUIRED.filter(id=>{const m=models.find(x=>x.id===id);return !m||!m.long_context||!(m.long_context.threshold>0&&m.long_context.input>0&&m.long_context.output>0)});
if(bad.length){console.error('BUILD GUARD: missing/invalid long_context tier for: '+bad.join(', '));process.exit(1)}}
// Guard (RT-20261031-63): every priced text row needs a sourced context window (the finder skips null context), unless explicitly flagged context_unpublished:true with a context_note.
{const bad=models.filter(m=>m.kind==='text'&&m.input!=null&&!m.context_unpublished&&!(Number.isInteger(m.context)&&m.context>0&&m.context_source)).map(m=>m.id),badFlag=models.filter(m=>m.context_unpublished&&(!m.context_note||m.context)).map(m=>m.id);
if(bad.length||badFlag.length){console.error('BUILD GUARD: priced text rows missing context/context_source: '+bad.join(', ')+(badFlag.length?' | context_unpublished rows need context_note and null context: '+badFlag.join(', '):''));process.exit(1)}}const pct=(o,n)=>(n-o)/o*100;
const pid=n=>n.toLowerCase().replace(/[^a-z0-9]+/g,'-');models.forEach(m=>m.provider_id=pid(m.provider));
const nVer=models.filter(m=>m.status==='verified').length,lastChecked=models.map(m=>m.checked).sort().at(-1);
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const usd=v=>v==null?'—':'$'+(v>=0.1?Number(v).toFixed(2):v>=0.01?Number(v).toFixed(3):Number(v).toFixed(4));const ctx=v=>v?(v>=1e6?(+(v/1e6).toFixed(2))+'M':Math.round(v/1e3)+'K'):'—';
fs.rmSync(D,{recursive:true,force:true});for(const d of ['','models','providers','api','assets','assets/og'])fs.mkdirSync(path.join(D,d),{recursive:true});
const W=(p,s)=>{fs.mkdirSync(path.dirname(path.join(D,p)),{recursive:true});fs.writeFileSync(path.join(D,p),s)};
const mark=`<svg width="22" height="22" viewBox="0 0 32 32" aria-hidden="true"><rect width="32" height="32" rx="5" fill="#0f1729"/><path d="M8 22h16M8 16h11M8 10h16" stroke="#fbfaf7" stroke-width="2.2" stroke-linecap="square"/><rect x="21" y="14" width="4" height="4" fill="#3fb68b"/></svg>`;
const signup=(id='s')=>`<form class="signup" action="${FORM_ACTION}" method="post" data-form="digest"><label for="${id}-e" class="skip">Work email</label><input id="${id}-e" type="email" name="email_address" required placeholder="you@company.com" autocomplete="email"><button class="btn" type="submit">Get the weekly digest</button></form><p class="note">One email a week: what changed in AI API pricing, with sources. Free; unsubscribe in one click. Sent via Kit · <a href="/privacy">Privacy</a>.</p>`;
const NAV=[['/','Rates'],['/calculator','Calculator'],['/compare','Compare'],['/changes','Change log'],['/providers/','Providers'],['/pro','Pro'],['/developers','API']];
const WEBSITE_LD={'@context':'https://schema.org','@type':'WebSite','@id':SITE+'/#website',name:NAME,url:SITE+'/',description:'Published AI API list prices (USD per 1M tokens), sourced and dated.',inLanguage:'en',publisher:{'@id':SITE+'/#org'}};
const ORG_LD={'@context':'https://schema.org','@type':'Organization','@id':SITE+'/#org',name:NAME,url:SITE+'/',sameAs:['https://github.com/Basileion/ratecard','https://bsky.app/profile/o11ywatch.bsky.social']};
const cleanPath=f=>f.replace(/index\.html$/,'').replace(/\.html$/,'');
const page=({file,title,desc,body,og='home',ld=[]})=>{const url=SITE+'/'+cleanPath(file);W(file,`<!doctype html><html lang="en" data-product="ratecard"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="msvalidate.01" content="C3E6B12179D5F715C605360B311848B3">
<title>${esc(title)}</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${url}"><meta name="robots" content="index,follow">
<meta property="og:type" content="website"><meta property="og:site_name" content="${NAME}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${url}"><meta property="og:image" content="${SITE}/assets/og/${og}.png"><meta name="twitter:card" content="summary_large_image">
${HEADSLOT}<link rel="manifest" href="/manifest.webmanifest"><meta name="theme-color" content="#0f1729"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/assets/icon-192.png">
<link rel="alternate" type="application/rss+xml" title="${NAME} change log" href="/rss.xml"><link rel="stylesheet" href="/assets/style.css">
${(['404.html','offline.html'].includes(file)?[]:[...(file==='index.html'?[WEBSITE_LD]:[]),...(ld.length?ld:[{'@context':'https://schema.org','@type':'WebPage',name:title,description:desc,url,isPartOf:{'@id':SITE+'/#website'}}])]).map(x=>`<script type="application/ld+json">${JSON.stringify(x)}</script>`).join('')}</head><body><a class="skip" href="#main">Skip to content</a>
<header class="top"><div class="wrap"><a class="brand" href="/">${mark}${NAME}<small>AI API rates</small></a><nav class="main" aria-label="Main">${NAV.map(([h,l])=>`<a href="${h}"${'/'+cleanPath(file)===h?' aria-current="page"':''}>${l}</a>`).join('')}</nav><a class="btn cta" href="/#digest">Weekly digest</a></div></header>
<main id="main" class="wrap">${body}</main>
<footer class="ds-foot"><div class="wrap"><div class="brand-blurb"><b style="display:block;font-family:var(--f-serif);font-size:16px;color:var(--ink);margin-bottom:8px">${NAME}</b><p>${NAME} — published AI API rates, sourced and dated. Last full check ${lastChecked}. Not affiliated with any provider; prices are list prices before negotiated discounts and taxes.</p></div><div class="col"><h3>Product</h3><nav aria-label="Product"><a href="/">Models</a><a href="/calculator">Calculator</a><a href="/compare">Compare</a><a href="/pro">Pro</a></nav></div><div class="col"><h3>Data</h3><nav aria-label="Data"><a href="/scheduled-increases">Scheduled increases</a><a href="/methodology">Methodology</a><a href="/api/models.csv">CSV</a><a href="/openapi.json">OpenAPI</a><a href="/rss.xml">RSS</a><a href="/llms.txt">llms.txt</a></nav></div><div class="col"><h3>Money</h3><nav aria-label="Money"><a href="/sponsor">Sponsor</a><a href="/developers">Cite / API</a></nav></div><div class="col"><h3>Legal</h3><nav aria-label="Legal"><a href="/about">About</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="${CONTACT}">Contact</a></nav></div><div class="portfolio" role="navigation" aria-label="More pricing ledgers"><div class="eyebrow">More pricing ledgers</div><ul><li><a href="https://o11y-watch.pages.dev/" rel="noopener">O11y Watch</a> — observability vendor free tiers and paid_from prices, sourced.</li><li><a href="https://vpsledger.pages.dev/" rel="noopener">VPSLedger</a> — VPS true monthly cost after promos, fees, and egress.</li><li><a href="https://authcost.pages.dev/" rel="noopener">AuthCost</a> — auth and identity MAU/MRU + SSO list prices.</li></ul></div><div class="legal">Verify on the provider’s pricing page before buying. <a href="/privacy">Privacy</a> · <a href="/terms">Terms</a></div></div></footer>
<script>window.__GROW__={site:"ratecardai.pages.dev"/* dormant A/B: ,experiments:[{id:"design-standard-v1",arms:["control","v1"]}] */};</script><script src="/assets/grow.js" defer></script><script type="module" src="/assets/app.js"></script></body></html>`)};
const provOpts=providers.map(p=>`<option>${esc(p.name)}</option>`).join('');
const faq=[['Where do these prices come from?','Each row is read from the provider’s own published pricing page or official API (OpenRouter’s public models endpoint for OpenRouter rows). Every row links that source and shows the date we checked it.'],['What does “Unverified” mean?','We could not read a price from the official page on the check date (for example, it is rendered client-side, region-dependent, or listed as “Contact sales”). We show the row so the gap is visible, and never guess a number.'],['How is the calculator’s cost computed?','Monthly cost = uncached input × input rate + cached input × cached rate + output × output rate, blended with batch rates for the share of traffic you mark as batch. When a typical prompt size exceeds a model long-context threshold, the long-context rates are used. Cache-write MTok/mo (OpenAI 30m/12h or Anthropic 5m/1h) are billed at the published write rate when you enter a volume and the model has those fields; otherwise the write line is N/A. DeepSeek Search/Fetch requests add $0.75 per 1,000 successful requests. Still excludes taxes and negotiated discounts.'],['How often is the data checked?','A script snapshots every source page weekly and diffs it. Confirmed changes are written to the change log and the RSS feed.'],['Can I use the data in my own tools?','Yes. The JSON API, OpenAPI spec and llms.txt are free to use with attribution.']];
const faqLd={'@context':'https://schema.org','@type':'FAQPage',mainEntity:faq.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))};
