if(!SA_F||SA_F.monthly!==2800||SA_F.total!==67200||SA_F.runRate!==33600){console.error('BUILD GUARD (pro sample): Argon @800/120 must be $2,800/mo, Next-12 $67,200, run-rate×12 $33,600; got',SA_F&&SA_F.monthly,SA_F&&SA_F.total,SA_F&&SA_F.runRate);process.exit(1)}
