const MAIL=CONTACT.replace(/^mailto:/,'');const legalHero=(eb,h,lede)=>`<section class="hero narrow"><div class="eyebrow">${eb} · updated ${LEGAL_UPDATED}</div><h1>${h}</h1><p class="lede">${lede}</p></section>`;
